import type { Quantity } from "../../reality/quantity";
import type { DemandProfile } from "../workload/profiles";
import type { WorkStation, WorkloadInput, StationState } from "../workload/contracts";

export interface ComputeProfile extends Omit<DemandProfile, "schema" | "io" | "stage"> {
  schema: "infraforge-compute-demand/1";
  stage: "compute";
  blockingWait: Quantity<"us">;
  maxCpuParallelism: Quantity<"cores">;
  residentCoverage: "complete-model" | "partial";
  requestResidentBytes?: Quantity<"bytes">;
  activeResidentBytes?: Quantity<"bytes">;
  residentComponents?: Array<{ id: string; owner: "admitted" | "active"; bytes: Quantity<"bytes"> }>;
}
export interface ComputeResource extends Omit<WorkStation, "kind" | "concurrency"> {
  kind: "compute";
  workers: Quantity<"count">;
  scheduler: "capped-equal-fluid/1";
  quota?: { budget: Quantity<"cpu-us">; period: Quantity<"us"> };
  memory: { coverage: "complete-model" | "partial"; baseline?: Quantity<"bytes">; perWorker?: Quantity<"bytes">; retained?: Quantity<"bytes">;
    components?: Array<{ id: string; owner: "process" | "worker"; bytes: Quantity<"bytes"> }>;
    limit?: Quantity<"bytes">; policy: "observe" | "reject-allocation" };
}
export type ComputeIntervention = { id: string; target: string; at: Quantity<"us"> } & (
  { kind: "capacity"; cores: Quantity<"cores"> } |
  { kind: "competitor"; duration: Quantity<"us">; demand: Quantity<"cpu-us">; parallelism: Quantity<"cores"> });
export interface ComputeInput extends Omit<WorkloadInput, "workloadVersion" | "profiles" | "resources"> {
  workloadVersion: "m2c/1";
  profiles: Array<ComputeProfile | DemandProfile>;
  resources: Array<ComputeResource | (WorkStation & { kind: "database" }) | { id: string; kind: "router"; backends: string[] }>;
  interventions: ComputeIntervention[];
}
export interface ComputeState extends StationState {
  compute?: {
    workers: { configured: number; idle: number; runnable: number; blockedWait: number; blockedDependency: number };
    cpu: { capacity: number; runnable: number; receivingShare: number; contended: boolean; paused: boolean; throttled: boolean;
      appCoreUs: number; competitorCoreUs: number; availableCoreUs: number; throttledWallUs: number; unsatisfiedParallelismUs: number;
      quotaRemainingCoreUs: number | null; allocations: Array<{ id: string; cores: number; remainingCoreUs: number }> };
    memory: { ownership: { requests: number; active: number }; knownSubtotalBytes: number; totalResidentBytes: Quantity<"bytes">; components: Record<string, Quantity<"bytes"> >; limitBytes: number | null; comparison: "unknown" | "within" | "exceeds"; policy: string };
    symptoms: string[];
    allocationRejected: number;
  };
}

import { requireKnown } from "../../reality/quantity";
import type { EventKernel } from "../time";
import type { Invocation, Receipt, RemoteOutcome } from "../workload/contracts";
import type { ComputeResource, ComputeProfile, ComputeState } from "./contracts";
import { identity } from "../workload/arrivals";
import { cpuScheduler } from "./scheduler";
import { residentMemory } from "./memory";
import type { CausalObserver } from "../workload/causal";

interface Call { work: Invocation; phase: "queued" | "cpu" | "wait" | "dependency" | "finished";
  done(outcome: RemoteOutcome): void; child?: Receipt; cancelWait?: () => boolean; waitRemaining: number; waitSince: number }
export function computeResource(config: ComputeResource, profiles: Map<string, ComputeProfile>, kernel: EventKernel,
  send: (target: string, work: Invocation, done: Call["done"]) => Receipt, causal?: CausalObserver) {
  const workers = requireKnown(config.workers, "count"), capacity = requireKnown(config.queueCapacity, "count");
  const scheduler = cpuScheduler(config.id, requireKnown(config.cores, "cores"), kernel, config.quota ? { budget: requireKnown(config.quota.budget, "cpu-us"), period: requireKnown(config.quota.period, "us") } : undefined);
  const memory = residentMemory(config, profiles), active = new Map<string, Call>(), queue = new Map<string, Call>();
  let paused = false, received = 0, admitted = 0, rejected = 0, completed = 0, failed = 0, cancelled = 0, allocationRejected = 0, pumping = false;
  let occupancyAt = kernel.now, occupancy = 0;
  const accountOccupancy = () => { occupancy += active.size * (kernel.now - occupancyAt); occupancyAt = kernel.now; };
  const finish = (call: Call, outcome: RemoteOutcome) => {
    if (call.phase === "finished") return;
    if (call.phase === "cpu") scheduler.remove(call.work.callId);
    accountOccupancy(); call.cancelWait?.(); active.delete(call.work.callId); queue.delete(call.work.callId); memory.release(call.work.callId); call.phase = "finished";
    if (outcome === "completed") completed++; else if (outcome === "cancelled") cancelled++; else failed++;
    causal?.({ atUs: kernel.now, kind: "app-terminal", resource: config.id, work: call.work, detail: { outcome } });
    call.done(outcome); pump();
  };
  const scheduleWait = (call: Call) => {
    if (paused) return;
    call.waitSince = kernel.now;
    call.cancelWait = kernel.schedule(kernel.now + call.waitRemaining, 2, identity("blocking-wait", config.id, call.work.callId), () => {
      call.waitRemaining = 0;
      if (config.downstream) {
        call.phase = "dependency";
        const child = { ...call.work, parentCallId: call.work.callId, callId: identity(...JSON.parse(call.work.callId), "dependency", config.downstream) };
        causal?.({ atUs: kernel.now, kind: "app-dependency", resource: config.id, work: child, detail: { target: config.downstream } });
        call.child = send(config.downstream, child, (outcome) => finish(call, outcome));
      } else finish(call, "completed");
    });
  };
  const pump = () => {
    if (pumping) return;
    pumping = true;
    while (!paused && active.size < workers && queue.size) {
      const call = queue.values().next().value!; queue.delete(call.work.callId);
      if (!memory.activate(call.work.callId)) { allocationRejected++; finish(call, "rejected"); continue; }
      accountOccupancy(); active.set(call.work.callId, call); call.phase = "cpu";
      causal?.({ atUs: kernel.now, kind: "app-start", resource: config.id, work: call.work, detail: {} });
      const p = profiles.get(call.work.operation)!;
      scheduler.add({ id: call.work.callId, demand: requireKnown(p.cpu, "cpu-us"), cap: requireKnown(p.maxCpuParallelism, "cores"), done: () => {
        if (call.phase === "finished") return;
        call.phase = "wait"; call.waitRemaining = requireKnown(p.blockingWait, "us"); scheduleWait(call);
      } });
    }
    pumping = false;
  };
  return {
    accept(work: Invocation, done: Call["done"]): Receipt {
      received++;
      const full = queue.size >= capacity && (paused || active.size >= workers);
      const memoryAccepted = !full && memory.acquire(work.callId, work.operation, false);
      if (full || !memoryAccepted) {
        if (!full) allocationRejected++;
        rejected++; causal?.({ atUs: kernel.now, kind: "app-rejected", resource: config.id, work, detail: {} }); done("rejected"); return { admitted: false, cancel: () => "already-finished", state: () => "finished" };
      }
      admitted++;
      causal?.({ atUs: kernel.now, kind: "app-admitted", resource: config.id, work, detail: {} });
      const call: Call = { work, done, phase: "queued", waitRemaining: 0, waitSince: kernel.now };
      queue.set(work.callId, call); pump();
      return { admitted: true, state: () => call.phase === "cpu" || call.phase === "wait" ? "serving" : call.phase === "dependency" ? "waiting" : call.phase,
        cancel: () => { if (call.phase === "finished") return "already-finished"; if (config.cancellation === "unsupported") return "unsupported";
          const child = call.child; finish(call, "cancelled"); child?.cancel(); return "cancelled"; } };
    },
    pause(value: boolean) {
      if (value === paused) throw new Error("Overlapping/unmatched compute pause");
      if (value) for (const call of active.values()) if (call.phase === "wait") { call.waitRemaining -= kernel.now - call.waitSince; call.cancelWait?.(); }
      paused = value; scheduler.pause(value);
      if (!paused) { for (const call of active.values()) if (call.phase === "wait") scheduleWait(call); pump(); }
    },
    setCapacity(cores: number) { scheduler.capacity(cores); },
    abortOwned() { for (const call of [...active.values(), ...queue.values()]) { const child = call.child; finish(call, "rejected"); child?.cancel(); } },
    competitor(id: string, demand: number, parallelism: number) { scheduler.add({ id, demand, cap: parallelism, competitor: true, done: () => {} }); },
    removeCompetitor(id: string) { scheduler.remove(id); },
    measure(): ComputeState {
      const cpu = scheduler.measure(), resident = memory.measure();
      const blockedWait = [...active.values()].filter((c) => c.phase === "wait").length, blockedDependency = [...active.values()].filter((c) => c.phase === "dependency").length;
      const runnable = active.size - blockedWait - blockedDependency;
      return { id: config.id, paused, received, admitted, rejected, completed, failed, cancelled, queued: queue.size, serving: runnable + blockedWait, waiting: blockedDependency,
        consumedCoreUs: cpu.appCoreUs, busySlotUs: occupancy + active.size * (kernel.now - occupancyAt), compute: { workers: { configured: workers, idle: workers - active.size, runnable, blockedWait, blockedDependency }, cpu, memory: resident, allocationRejected,
          symptoms: [ ...(paused || cpu.capacity === 0 ? ["unavailable"] : []), ...(queue.size ? ["backpressured"] : []), ...(cpu.throttled ? ["cpu-throttled"] : []), ...(cpu.contended && !cpu.throttled ? ["cpu-contended"] : []), ...(resident.comparison === "exceeds" ? ["modeled-resident-limit-exceeded"] : []) ] } };
    },
  };
}

import { requireKnown } from "../../reality/quantity";
import type { ComputeInput, ComputeState } from "./contracts";
import type { WorkloadInput } from "../workload/contracts";
import { createWorkloadRuntime } from "../workload/run";
import { workloadStation } from "../workload/station";
import { computeResource } from "./resource";
import { validateCompute, isCompute, isComputeProfile } from "./validate";
import { COMPUTE_POLICY_LEDGER } from "./policy";
import { validateWorkload } from "../workload/validate";
import { lexical } from "../time";
import type { EventKernel } from "../time";
import type { Invocation, Receipt, RemoteOutcome } from "../workload/contracts";
import type { WorkEndpoint } from "../workload/run";
import type { CausalObserver } from "../workload/causal";

const copy = <T>(value: T): T => JSON.parse(JSON.stringify(value));
export type Deliver = (target: string, work: Invocation, done: (outcome: RemoteOutcome) => void) => Receipt;
export interface ComputeComposition {
  send(source: string, target: string, work: Invocation, done: (outcome: RemoteOutcome) => void): Receipt;
  receive(target: string, work: Invocation, done: (outcome: RemoteOutcome) => void, direct: () => Receipt): Receipt;
}
export type ResourceFactory = (id: string, kernel: EventKernel, send: Deliver) => WorkEndpoint<ComputeState> | undefined;
export function createComputeModel2(authored: ComputeInput) {
  return createComputeRuntime(authored);
}
const adapt = (source: ComputeInput): WorkloadInput => ({ ...source, workloadVersion: "m2b/1",
    profiles: source.profiles.map((p) => isComputeProfile(p) ? { ...p, schema: "infraforge-demand/1", io: p.blockingWait } : p),
    resources: source.resources.map((r) => isCompute(r) ? { ...r, concurrency: r.workers } : r) });
export function validateComputeInput(authored: ComputeInput) {
  // Preserve M2B's pre-copy trace/request budgets at the new resource seam.
  validateWorkload(adapt(authored));
  validateCompute(authored);
}
export function createComputeRuntime(authored: ComputeInput, compose?: (kernel: EventKernel, deliver: Deliver, controls: { pause(id: string, value: boolean): void; observe(id: string): unknown; abortOwned(id: string): void }) => ComputeComposition, resourceFactory?: ResourceFactory, causal?: CausalObserver) {
  validateComputeInput(authored);
  const input: ComputeInput = JSON.parse(JSON.stringify(authored));
  for (const list of [input.resources, input.profiles, input.operations, input.arrivals, input.faults, input.ledger, input.interventions]) list.sort((a, b) => lexical(a.id, b.id));
  const adapter = adapt(input);
  const computes = new Map<string, ReturnType<typeof computeResource>>();
  let composition: ComputeComposition | undefined;
  let deliverEntry: Deliver;
  const interventionEvidence: Array<{ id: string; at: number; state: string }> = [];
  const runtime = createWorkloadRuntime<ComputeState>(adapter, {
    causal,
    station(config, demands, kernel, send) {
      const original = input.resources.find((r) => r.id === config.id)!;
      const external = resourceFactory?.(original.id, kernel, (target, work, done) => composition ? composition.send(original.id, target, work, done) : send(target, work, done));
      if (external) return external;
      if (!isCompute(original)) return workloadStation(config, demands, kernel, (target, work, done) => composition ? composition.send(original.id, target, work, done) : send(target, work, done));
      const profiles = new Map(input.operations.map((o) => [o.id, input.profiles.find((p) => p.id === original.profiles[o.id])!]).filter((pair): pair is [string, Extract<ComputeInput["profiles"][number], { schema: "infraforge-compute-demand/1" }>] => typeof pair[0] === "string" && typeof pair[1] === "object" && isComputeProfile(pair[1])));
      const resource = computeResource(original, profiles, kernel, (target, work, done) => composition ? composition.send(original.id, target, work, done) : send(target, work, done), causal); computes.set(original.id, resource); return resource;
    },
    route: (target, work, done, direct) => composition ? composition.receive(target, work, done, direct) : direct(),
    enter: (target, work, done) => composition ? composition.send("$caller", target, work, done) : deliverEntry(target, work, done),
    install(kernel, _stations, send) {
      deliverEntry = send; composition = compose?.(kernel, send, { pause: (id, value) => _stations.get(id)!.pause(value), observe: (id) => _stations.get(id)?.measure(), abortOwned: (id) => computes.get(id)?.abortOwned() });
      for (const i of [...input.interventions].sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0)) {
        const at = requireKnown(i.at, "us"), resource = computes.get(i.target)!;
        kernel.schedule(at, 0, JSON.stringify(["compute-intervention", i.id]), () => {
          if (i.kind === "capacity") resource.setCapacity(requireKnown(i.cores, "cores"));
          else resource.competitor(JSON.stringify(["competitor", i.id]), requireKnown(i.demand, "cpu-us"), requireKnown(i.parallelism, "cores"));
          interventionEvidence.push({ id: i.id, at: kernel.now, state: "applied" });
        });
        if (i.kind === "competitor") kernel.schedule(at + requireKnown(i.duration, "us"), -1, JSON.stringify(["compute-intervention-end", i.id]), () => {
          resource.removeCompetitor(JSON.stringify(["competitor", i.id])); interventionEvidence.push({ id: i.id, at: kernel.now, state: "ended" });
        });
      }
    },
  });
  return { horizon: runtime.horizon, advanceTo: runtime.advanceTo,
    evidence() { const e = runtime.evidence();
      const intervals = e.samples.slice(1).flatMap((sample, index) => sample.resources.flatMap((resource) => {
        const current = resource.compute?.cpu, previous = e.samples[index]!.resources.find((r) => r.id === resource.id)?.compute?.cpu;
        if (!current || !previous) return [];
        const appCoreUs = current.appCoreUs - previous.appCoreUs, competitorCoreUs = current.competitorCoreUs - previous.competitorCoreUs, availableCoreUs = current.availableCoreUs - previous.availableCoreUs;
        return [{ resource: resource.id, fromUs: e.samples[index]!.at, toUs: sample.at, appCoreUs, competitorCoreUs, availableCoreUs,
          utilization: availableCoreUs > 0 ? { kind: "known", unit: "ratio", app: appCoreUs / availableCoreUs, total: (appCoreUs + competitorCoreUs) / availableCoreUs } : { kind: "unknown", unit: "ratio", reason: "No available core-time in interval" } }];
      }));
      return { ...e, workloadVersion: "m2c/1" as const, intervals, computePolicyLedger: copy(COMPUTE_POLICY_LEDGER), computeProfiles: copy(input.profiles.filter(isComputeProfile)), computeConfiguration: copy(input.resources.filter(isCompute)), interventions: copy(interventionEvidence),
      unmodeled: ["network transport latency", "cost", "database locks", "packet loss", "GC", "reclaim/swap/OOM", "physical topology/SMT/frequency behavior outside calibrated workload points"] }; } };
}

import { lexical, type EventKernel } from "../time";
import { fairShares } from "./sharing";

interface Job { id: string; cap: number; remaining: number; competitor: boolean; done(): void }
export function cpuScheduler(id: string, initialCapacity: number, kernel: EventKernel, quota?: { budget: number; period: number }) {
  const jobs = new Map<string, Job>(); let rates = new Map<string, number>();
  let capacity = initialCapacity, paused = false, anchor = kernel.now, available = 0, app = 0, competitor = 0, throttled = 0, pressure = 0;
  let budget = quota?.budget ?? Infinity, period = quota ? Math.floor(kernel.now / quota.period) : 0;
  let cancelBoundary: (() => boolean) | undefined, updating = false, boundaries = 0;
  const projection = () => {
    const dt = kernel.now - anchor, totalRate = [...rates.values()].reduce((a, b) => a + b, 0);
    const serviceDt = totalRate > 0 ? Math.min(dt, budget / totalRate) : 0;
    let usedApp = 0, usedCompetitor = 0;
    const remaining = new Map<string, number>();
    for (const j of jobs.values()) {
      const consumed = Math.min(j.remaining, (rates.get(j.id) ?? 0) * serviceDt);
      remaining.set(j.id, Math.max(0, j.remaining - consumed));
      if (j.competitor) usedCompetitor += consumed; else usedApp += consumed;
    }
    const wanted = [...jobs.values()].reduce((sum, j) => sum + j.cap, 0);
    const granted = [...rates.values()].reduce((a, b) => a + b, 0);
    return { remaining, usedApp, usedCompetitor, available: capacity * dt,
      throttled: !paused && jobs.size && quota ? (budget <= 0 ? dt : usedApp + usedCompetitor >= budget && totalRate > 0 ? dt - serviceDt : 0) : 0,
      pressure: paused ? 0 : Math.max(0, wanted * dt - granted * serviceDt) };
  };
  const settle = () => {
    const p = projection(); available += p.available; app += p.usedApp; competitor += p.usedCompetitor; throttled += p.throttled; pressure += p.pressure;
    for (const [key, remaining] of p.remaining) jobs.get(key)!.remaining = remaining;
    budget = Math.max(0, budget - p.usedApp - p.usedCompetitor); anchor = kernel.now;
    if (quota && Math.floor(kernel.now / quota.period) > period) { period = Math.floor(kernel.now / quota.period); budget = quota.budget; }
  };
  const reschedule = () => {
    if (updating) return;
    cancelBoundary?.(); cancelBoundary = undefined;
    rates = fairShares([...jobs.values()], paused || budget <= 0 ? 0 : capacity);
    if (!jobs.size) return;
    let delay = !paused && [...jobs.values()].some((j) => j.remaining <= 0) ? 0 : Infinity;
    for (const j of jobs.values()) { const rate = rates.get(j.id) ?? 0; if (rate > 0) delay = Math.min(delay, Math.max(1, Math.ceil(j.remaining / rate))); }
    const totalRate = [...rates.values()].reduce((a, b) => a + b, 0);
    if (quota) {
      if (totalRate > 0) delay = Math.min(delay, Math.max(1, Math.ceil(budget / totalRate)));
      // Replenishment is a meaningful boundary, not a scheduling quantum.
      if (!paused) delay = Math.min(delay, (period + 1) * quota.period - kernel.now);
    }
    if (!Number.isFinite(delay)) return;
    cancelBoundary = kernel.schedule(kernel.now + delay, 2, JSON.stringify(["cpu-boundary", id]), () => {
      boundaries++; settle(); updating = true;
      const finished = [...jobs.values()].filter((j) => j.remaining <= 0).sort((a, b) => lexical(a.id, b.id));
      for (const j of finished) jobs.delete(j.id);
      for (const j of finished) j.done();
      updating = false; reschedule();
    });
  };
  return {
    add(job: { id: string; demand: number; cap: number; competitor?: boolean; done(): void }) {
      settle(); if (jobs.has(job.id)) throw new Error("Duplicate runnable invocation");
      if (job.demand <= 0) { job.done(); reschedule(); return; }
      jobs.set(job.id, { id: job.id, cap: job.cap, remaining: job.demand, competitor: job.competitor ?? false, done: job.done }); reschedule();
    },
    remove(key: string) { settle(); jobs.delete(key); reschedule(); },
    pause(value: boolean) { settle(); paused = value; reschedule(); },
    capacity(value: number) { settle(); capacity = value; reschedule(); },
    measure() {
      const p = projection(), remainingBudget = quota && Math.floor(kernel.now / quota.period) > period ? quota.budget : Math.max(0, budget - p.usedApp - p.usedCompetitor);
      return { capacity, runnable: jobs.size, receivingShare: [...rates.values()].filter((r) => r > 0).length,
        contended: !paused && [...jobs.values()].some((j) => (rates.get(j.id) ?? 0) < j.cap), paused,
        throttled: !paused && jobs.size > 0 && remainingBudget <= 0,
        appCoreUs: app + p.usedApp, competitorCoreUs: competitor + p.usedCompetitor, availableCoreUs: available + p.available,
        throttledWallUs: throttled + p.throttled, unsatisfiedParallelismUs: pressure + p.pressure,
        quotaRemainingCoreUs: quota ? remainingBudget : null,
        allocations: [...jobs.values()].sort((a, b) => lexical(a.id, b.id)).map((j) => ({ id: j.id, cores: rates.get(j.id) ?? 0, remainingCoreUs: p.remaining.get(j.id)! })), boundaries };
    },
  };
}

import { requireKnown, validateQuantity, type Quantity, type Unit } from "../../reality/quantity";
import type { ComputeInput, ComputeResource, ComputeProfile } from "./contracts";
import { micros } from "../time";
import { COMPUTE_LIMITS } from "./policy";

export function validateCompute(input: ComputeInput) {
  if (input.workloadVersion !== "m2c/1" || input.resources.length > 256 || input.profiles.length > 16384 || input.interventions.length > COMPUTE_LIMITS.interventions) throw new Error("Invalid compute revision/structural budget");
  const ledger = new Map(input.ledger.map((e) => [e.id, e.quantity]));
  const check = (q: Quantity, unit: Unit, min = 0, unknown = false, integer = false) => {
    if (validateQuantity(q).length || q.unit !== unit || (!unknown && q.kind !== "known")) throw new Error(`Unknown/invalid compute ${unit}`);
    for (const id of q.provenance) {
      const e = ledger.get(id);
      if (!e || e.unit !== q.unit || e.kind !== q.kind || (e.kind === "known" && q.kind === "known" && e.value !== q.value) || (e.kind === "range" && q.kind === "range" && (e.min !== q.min || e.max !== q.max)) || (e.kind === "unknown" && q.kind === "unknown" && e.reason !== q.reason)) throw new Error(`Missing exact compute provenance: ${id}`);
    }
    if (q.kind === "known" && (q.value < min || (integer && !Number.isSafeInteger(q.value)))) throw new Error("Invalid compute quantity bounds");
    if (q.kind === "range" && (q.min < min || (integer && (!Number.isSafeInteger(q.min) || !Number.isSafeInteger(q.max))))) throw new Error("Invalid memory bound");
  };
  const components = (parts: Array<{ id: string; owner: string; bytes: Quantity<"bytes"> }>, owners: string[]) => {
    if (parts.length > COMPUTE_LIMITS.memoryComponents || new Set(parts.map((p) => p.id)).size !== parts.length || parts.some((p) => !p.id || !owners.includes(p.owner))) throw new Error("Invalid resident component ownership/budget");
    for (const p of parts) check(p.bytes, "bytes", 0, true, true);
  };
  const defined = <T>(q: T | undefined): q is T => q !== undefined;
  for (const p of input.profiles) if (p.schema === "infraforge-compute-demand/1") {
    check(p.maxCpuParallelism, "cores", Number.MIN_VALUE); check(p.blockingWait, "us", 0, false, true);
    if (!["complete-model", "partial"].includes(p.residentCoverage)) throw new Error("Resident profile coverage required");
    for (const q of [p.requestResidentBytes, p.activeResidentBytes].filter(defined)) check(q, "bytes", 0, true, true);
    components(p.residentComponents ?? [], ["admitted", "active"]);
  }
  const resources = new Map(input.resources.map((r) => [r.id, r]));
  for (const r of input.resources) if (r.kind === "compute") {
    if (!Number.isFinite(requireKnown(r.cores, "cores") * requireKnown(input.horizon, "us"))) throw new Error("Available core-time overflow");
    if (r.scheduler !== "capped-equal-fluid/1" || requireKnown(r.workers, "count") > COMPUTE_LIMITS.workers || !["observe", "reject-allocation"].includes(r.memory.policy)) throw new Error("Unsupported scheduler/workers/memory policy");
    if (!["complete-model", "partial"].includes(r.memory.coverage)) throw new Error("Resident process coverage required");
    for (const q of [r.memory.baseline, r.memory.perWorker, r.memory.retained].filter(defined)) check(q, "bytes", 0, true, true);
    components(r.memory.components ?? [], ["process", "worker"]);
    if (r.memory.limit) check(r.memory.limit, "bytes", 0, false, true);
