    if (["partition", "bandwidth", "delay"].includes(i.kind) ? !links.has(i.target) : i.kind === "reset" ? !input.paths.some((p) => p.id === i.target) : !resourceIds.has(i.target)) throw new Error("Unknown intervention target");
    if (i.kind === "partition" || i.kind === "bandwidth" || i.kind === "delay" || i.kind === "service-state") {
      const end = micros(at + number(i.duration, "us", 1)), key = JSON.stringify([i.kind, i.target]), existing = spans.get(key) ?? [];
      if (existing.some(([a, b]) => at < b && end > a)) throw new Error("Overlapping network interventions unsupported"); existing.push([at, end]); spans.set(key, existing);
    }
    if (i.kind === "bandwidth") { const rate = number(i.bandwidth, "bytes/s", 0, false); if (!Number.isFinite(rate * horizon)) throw new Error("Bandwidth integral overflow"); }
    if (i.kind === "delay") micros(horizon + number(i.delay, "us"));
    if (i.kind === "service-state" && (typeof i.alive !== "boolean" || typeof i.ready !== "boolean")) throw new Error("Invalid endpoint state");
    if (i.kind === "service-state" && !i.alive && input.resources.find((r) => r.id === i.target)!.kind === "load-balancer") throw new Error("LB process suspension/restart is unmodeled; readiness gating is supported");
    if (i.kind === "drain") { const lb = input.resources.find((r) => r.id === i.target); if (lb?.kind !== "load-balancer" || !lb.backends.includes(i.backend)) throw new Error("Unknown draining backend"); micros(at + number(i.grace, "us")); }
  }
}

export type Micros = number & { readonly __unit: "us" };
export function micros(value: number): Micros {
  if (!Number.isSafeInteger(value) || value < 0) throw new Error("Time must be nonnegative safe integer microseconds");
  return value as Micros;
}
export const lexical = (a: string, b: string) => a < b ? -1 : a > b ? 1 : 0;
interface Event { at: Micros; priority: number; key: string; run: () => void; index: number }
const compare = (a: Event, b: Event) => a.at - b.at || a.priority - b.priority || lexical(a.key, b.key);

// Event time is independent of wall time and UI playback speed. Equal-time order is contractual.
export class EventKernel {
  now = micros(0);
  processed = 0;
  peakPending = 0;
  cancelled = 0;
  private heap: Event[] = [];
  private keys = new Set<string>();
  constructor(readonly maxEvents: number) {
    if (!Number.isSafeInteger(maxEvents) || maxEvents <= 0) throw new Error("Invalid event budget");
  }
  schedule(at: number, priority: number, key: string, run: () => void) {
    if (at < this.now || !Number.isSafeInteger(priority) || !key || this.keys.has(key)) throw new Error("Past, invalid or duplicate event");
    if (this.heap.length + this.processed >= this.maxEvents) throw new Error("Event budget exhausted; evidence is incomplete");
    const event = { at: micros(at), priority, key, run, index: this.heap.length };
    this.keys.add(key); this.heap.push(event);
    let i = this.heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >>> 1;
      if (compare(this.heap[parent]!, event) <= 0) break;
      this.heap[i] = this.heap[parent]!; this.heap[i]!.index = i; i = parent;
    }
    this.heap[i] = event; event.index = i; this.peakPending = Math.max(this.peakPending, this.heap.length);
    // Indexed removal releases callbacks immediately, without accumulating tombstones.
    return () => {
      if (event.index < 0) return false;
      this.remove(event.index); this.cancelled++; return true;
    };
  }
  get pending() { return this.heap.length; }
  private remove(index: number) {
    const removed = this.heap[index]!, last = this.heap.pop()!;
    removed.index = -1; this.keys.delete(removed.key);
    if (index >= this.heap.length) return removed;
    let i = index;
    if (i > 0 && compare(last, this.heap[(i - 1) >>> 1]!) < 0) {
      while (i > 0) {
        const parent = (i - 1) >>> 1;
        if (compare(this.heap[parent]!, last) <= 0) break;
        this.heap[i] = this.heap[parent]!; this.heap[i]!.index = i; i = parent;
      }
    } else {
      while (i * 2 + 1 < this.heap.length) {
        let child = i * 2 + 1;
        if (child + 1 < this.heap.length && compare(this.heap[child + 1]!, this.heap[child]!) < 0) child++;
        if (compare(last, this.heap[child]!) <= 0) break;
        this.heap[i] = this.heap[child]!; this.heap[i]!.index = i; i = child;
      }
    }
    this.heap[i] = last; last.index = i; return removed;
  }
  advanceTo(until: number) {
    micros(until);
    if (until < this.now) throw new Error("Cannot reverse simulation time");
    while (this.heap[0] && this.heap[0].at <= until) {
      const event = this.remove(0);
      this.now = event.at; this.processed++; event.run();
    }
    this.now = micros(until);
  }
}

import type { Quantity } from "../../reality/quantity";
import type { RealityEntry } from "../../reality/ledger";
import type { FaultPlan } from "../contracts";
import type { DemandProfile, ProfileContext } from "./profiles";

export interface OperationClass {
  id: string;
  entry: string;
  callerTimeout: Quantity<"us">;
  abandonAfter?: Quantity<"us">;
  onCallerStop: "detach" | "request-cancellation";
  idempotency: "read-only" | "idempotent" | "non-idempotent" | "unknown";
}
interface Source { id: string; operation: string; start: Quantity<"us"> }
export type ArrivalSource =
  | (Source & { kind: "periodic"; count: Quantity<"count">; interval: Quantity<"us"> })
  | (Source & { kind: "poisson"; count: Quantity<"count">; meanInterval: Quantity<"us"> })
  | (Source & { kind: "closed"; users: Quantity<"count">; perUser: Quantity<"count">; think: Quantity<"us"> })
  | { id: string; kind: "trace"; trace: ArrivalTrace };
export interface TraceRow { id: string; atUs: number; operation: string; payloadBytes?: number }
export interface ArrivalTrace {
  schema: "infraforge-arrivals/1";
  unit: "us";
  durationUs: number;
  provenance: string;
  rows: TraceRow[];
}
export interface WorkIdentity {
  rootId: string;
  attempt: number;
  callId: string;
  parentCallId?: string;
  operation: string;
}
export interface Invocation extends WorkIdentity {
  offeredAt: number; payloadBytes?: number;
  // Internal application messages are copied by transport; replies become visible on return.
  message?: { request: unknown; response?: unknown; bodyBytes?: { request?: number; response?: number } };
  sessionId?: string;
}
export type RemoteOutcome = "completed" | "rejected" | "cancelled";
export type CallerOutcome = "completed" | "rejected" | "deadline-exceeded" | "abandoned";
export interface Receipt {
  admitted: boolean;
  cancel(): "cancelled" | "unsupported" | "already-finished";
  state(): "queued" | "serving" | "waiting" | "finished";
}
export interface WorkStation {
  id: string;
  kind: "compute" | "database";
  cores: Quantity<"cores">;
  concurrency: Quantity<"count">;
  queueCapacity: Quantity<"count">;
  profiles: Record<string, string>;
  context: ProfileContext;
  cancellation: "cooperative" | "unsupported";
  downstream?: string;
}
export interface WorkRouter { id: string; kind: "router"; backends: string[] }
export interface WorkloadInput {
  modelVersion: "2";
  workloadVersion: "m2b/1";
  seed: string;
  ledger: RealityEntry[];
  profiles: DemandProfile[];
  resources: Array<WorkStation | WorkRouter>;
  operations: OperationClass[];
  arrivals: ArrivalSource[];
  faults: FaultPlan[];
  horizon: Quantity<"us">;
  sampleInterval: Quantity<"us">;
  limits: { maxEvents: number; maxSamples: number; maxRequests: number; maxRawResults: number; maxTraceRows: number };
}
export interface StationState {
  id: string;
  paused: boolean;
  received: number;
  admitted: number;
  rejected: number;
  completed: number;
  failed: number;
  cancelled: number;
  queued: number;
  serving: number;
  waiting: number;
  consumedCoreUs: number;
  busySlotUs: number;
}
export interface CallerResult extends WorkIdentity {
  offeredAt: number;
  at: number;
  outcome: CallerOutcome;
  responseUs: number;
}

import type { CallerOutcome, CallerResult } from "./contracts";
import { HISTOGRAM_BUCKETS, EMPIRICAL_QUANTILES } from "./policy";

const outcomes: CallerOutcome[] = ["completed", "rejected", "deadline-exceeded", "abandoned"];
// Log2 integer buckets cover safe integer microseconds. No observations are discarded.
export class ResultBook {
  readonly raw: CallerResult[] = [];
  private groups = new Map<string, { operation: string; outcome: CallerOutcome; count: number; sum: number; min: number; max: number; bins: number[] }>();
  constructor(readonly rawLimit: number) {}
  record(result: CallerResult) {
    if (!Number.isSafeInteger(result.responseUs) || result.responseUs < 0) throw new Error("Latency must be safe integer microseconds");
    const key = JSON.stringify([result.operation, result.outcome]);
    let group = this.groups.get(key);
    if (!group) {
      group = { operation: result.operation, outcome: result.outcome, count: 0, sum: 0, min: Infinity, max: 0, bins: Array(HISTOGRAM_BUCKETS).fill(0) };
      this.groups.set(key, group);
    }
    group.count++; group.sum += result.responseUs; group.min = Math.min(group.min, result.responseUs); group.max = Math.max(group.max, result.responseUs);
    // log2(MAX_SAFE_INTEGER) can round to 53 in IEEE-754; clamp its last bucket.
    group.bins[result.responseUs === 0 ? 0 : Math.min(HISTOGRAM_BUCKETS - 1, 1 + Math.floor(Math.log2(result.responseUs)))]!++;
    if (this.raw.length < this.rawLimit) this.raw.push(result);
  }
  summary() {
    return [...this.groups.values()].sort((a, b) => a.operation < b.operation ? -1 : a.operation > b.operation ? 1 : outcomes.indexOf(a.outcome) - outcomes.indexOf(b.outcome)).map((g) => {
      const exact = this.raw.filter((r) => r.operation === g.operation && r.outcome === g.outcome).map((r) => r.responseUs).sort((a, b) => a - b);
      const percentiles = EMPIRICAL_QUANTILES.map((p) => {
        // At least one expected observation beyond the requested empirical quantile.
        if (g.count < Math.round(1 / (1 - p))) return { p, kind: "unknown" as const, reason: "Insufficient terminal samples for this tail rank" };
        const rank = Math.ceil(p * g.count);
        if (exact.length === g.count) return { p, kind: "exact" as const, valueUs: exact[rank - 1]!, method: "empirical-nearest-rank" };
        let seen = 0, bucket = 0;
        for (; bucket < g.bins.length; bucket++) { seen += g.bins[bucket]!; if (seen >= rank) break; }
        return { p, kind: "bounded" as const, minUs: bucket === 0 ? 0 : 2 ** (bucket - 1), maxUs: bucket === 0 ? 0 : 2 ** bucket - 1, method: "log2-histogram-rank" };
      });
      return { operation: g.operation, outcome: g.outcome, count: g.count, minUs: g.min, maxUs: g.max,
        meanUs: g.sum / g.count, percentiles, histogram: { unit: "us", counts: [...g.bins], layout: "0 then [2^(i-1),2^i-1]" } };
    });
  }
}

import { EventKernel, lexical } from "../time";
import { requireKnown } from "../../reality/quantity";
import { identity, ingestTrace, openRows } from "./arrivals";
import { ResultBook } from "./evidence";
import { validateWorkload } from "./validate";
import { workloadStation } from "./station";
import { WORKLOAD_POLICY_LEDGER } from "./policy";
import type { CallerOutcome, Invocation, Receipt, RemoteOutcome, TraceRow, WorkloadInput, WorkStation, StationState } from "./contracts";
import type { CausalObserver } from "./causal";

export interface WorkEndpoint<M extends StationState> {
  accept(work: Invocation, done: (outcome: RemoteOutcome) => void): Receipt;
  pause(value: boolean): void;
  measure(): M;
}
export interface RuntimeModules<M extends StationState> {
  causal?: CausalObserver;
  station(config: WorkStation, demands: Map<string, { cpuUs: number; ioUs: number }>, kernel: EventKernel, send: (target: string, work: Invocation, done: (outcome: RemoteOutcome) => void) => Receipt): WorkEndpoint<M>;
  install?(kernel: EventKernel, stations: Map<string, WorkEndpoint<M>>, send: (target: string, work: Invocation, done: (outcome: RemoteOutcome) => void) => Receipt): void;
  route?(target: string, work: Invocation, done: (outcome: RemoteOutcome) => void, direct: () => Receipt): Receipt;
  enter?(target: string, work: Invocation, done: (outcome: RemoteOutcome) => void): Receipt;
}

// Separate internal workload revision; no public export, HTTP route or Model-1 dispatch.
export function createWorkloadModel2(authored: WorkloadInput) {
  return createWorkloadRuntime(authored, { station: workloadStation });
}

// Resource modules share arrival/identity/caller/evidence ownership, not physics.
export function createWorkloadRuntime<M extends StationState>(authored: WorkloadInput, modules: RuntimeModules<M>) {
  const copy = <T>(value: T): T => JSON.parse(JSON.stringify(value));
  // Enforce structural budgets before duplicating a potentially large authored trace.
  const demands = validateWorkload(authored), input = copy(authored);
  for (const list of [input.resources, input.operations, input.arrivals, input.profiles, input.faults, input.ledger]) list.sort((a, b) => lexical(a.id, b.id));
  for (const r of input.resources) if (r.kind === "router") r.backends.sort(lexical);
  for (const a of input.arrivals) if (a.kind === "trace") a.trace = ingestTrace(a.trace, a.trace.rows, input.limits.maxTraceRows, new Set(input.operations.map((o) => o.id)));
  const kernel = new EventKernel(input.limits.maxEvents), horizon = requireKnown(input.horizon, "us"), step = requireKnown(input.sampleInterval, "us");
  const stations = new Map<string, WorkEndpoint<M>>();
  const routers = new Map(input.resources.filter((r) => r.kind === "router").map((r) => [r.id, { backends: r.backends, next: 0 }]));
  const send = (target: string, work: Invocation, done: (outcome: RemoteOutcome) => void): Receipt => {
    const direct = () => {
      const router = routers.get(target);
      if (router) return send(router.backends[router.next++ % router.backends.length]!, work, done);
      return stations.get(target)!.accept(work, done);
    };
    return modules.route ? modules.route(target, work, done, direct) : direct();
  };
  for (const r of input.resources) if (r.kind !== "router") stations.set(r.id, modules.station(r, demands.get(r.id)!, kernel, send));
  modules.install?.(kernel, stations, send);
  const operations = new Map(input.operations.map((o) => [o.id, o]));
  const live = new Map<string, { work: Invocation; receipt?: Receipt }>();
  const book = new ResultBook(input.limits.maxRawResults);
  const counts = { offered: 0, admitted: 0, completed: 0, rejected: 0, deadlineExceeded: 0, abandoned: 0, remoteOutcomesAfterCallerStop: 0, cancellationRequested: 0, cancellationConfirmedAtEntry: 0 };
  const byOperation = new Map(input.operations.map((o) => [o.id, { offered: 0, completed: 0, rejected: 0, deadlineExceeded: 0, abandoned: 0 }]));
  const sources = new Map(input.arrivals.map((a) => [a.id, { offered: 0 }]));
  const offer = (source: string, row: TraceRow, next?: () => void) => {
    if (++counts.offered > input.limits.maxRequests) throw new Error("Request execution budget exceeded");
    sources.get(source)!.offered++;
    const operation = operations.get(row.operation)!, perOperation = byOperation.get(row.operation)!; perOperation.offered++;
    const rootId = identity("root", source, row.id), callId = identity(rootId, "attempt", 0, "entry");
    const work: Invocation = { rootId, attempt: 0, callId, operation: operation.id, offeredAt: kernel.now, ...(row.payloadBytes === undefined ? {} : { payloadBytes: row.payloadBytes }) };
    modules.causal?.({ atUs: kernel.now, kind: "caller-offered", resource: "$caller", work, detail: {} });
    const pending: { work: Invocation; receipt?: Receipt } = { work }; live.set(rootId, pending);
    let terminal = false, cancelDeadline: (() => boolean) | undefined, cancelAbandon: (() => boolean) | undefined;
    const finish = (outcome: CallerOutcome) => {
      if (terminal) return;
      terminal = true; live.delete(rootId); cancelDeadline?.(); cancelAbandon?.();
      const key = outcome === "deadline-exceeded" ? "deadlineExceeded" : outcome;
      counts[key]++; perOperation[key]++;
      modules.causal?.({ atUs: kernel.now, kind: "caller-terminal", resource: "$caller", work, detail: { outcome, responseUs: kernel.now - work.offeredAt } });
      book.record({ ...work, at: kernel.now, outcome, responseUs: kernel.now - work.offeredAt }); next?.();
    };
    const stop = (outcome: "deadline-exceeded" | "abandoned") => {
      finish(outcome);
      if (operation.onCallerStop === "request-cancellation" && pending.receipt) {
        counts.cancellationRequested++;
        if (pending.receipt.cancel() === "cancelled") counts.cancellationConfirmedAtEntry++;
      }
    };
    cancelDeadline = kernel.schedule(kernel.now + requireKnown(operation.callerTimeout, "us"), 1, identity("caller-stop", rootId, 0), () => stop("deadline-exceeded"));
    if (operation.abandonAfter) cancelAbandon = kernel.schedule(kernel.now + requireKnown(operation.abandonAfter, "us"), 1, identity("caller-stop", rootId, 1), () => stop("abandoned"));
    pending.receipt = (modules.enter ?? send)(operation.entry, work, (outcome) => {
      if (terminal) { counts.remoteOutcomesAfterCallerStop++; return; }
      finish(outcome === "completed" ? "completed" : "rejected");
    });
    if (pending.receipt.admitted) counts.admitted++;
  };
  const scheduleRow = (source: string, row: TraceRow, next?: () => void, offered?: () => void) => {
    if (row.atUs <= horizon) kernel.schedule(row.atUs, 3, identity("arrival", source, row.id), () => { offer(source, row, next); offered?.(); });
  };
  for (const a of input.arrivals) {
    if (a.kind === "closed") {
      const users = requireKnown(a.users, "count"), perUser = requireKnown(a.perUser, "count"), think = requireKnown(a.think, "us");
      for (let user = 0; user < users; user++) {
        const issue = (index: number, at: number) => {
          if (index < perUser) scheduleRow(a.id, { id: identity("user", user, index), atUs: at, operation: a.operation }, () => issue(index + 1, kernel.now + think));
        };
        issue(0, requireKnown(a.start, "us"));
      }
    } else {
      const iterator = openRows(a, input.seed);
      const advance = () => { const row = iterator.next(); if (!row.done) scheduleRow(a.id, row.value, undefined, advance); };
      advance();
    }
  }
  const faults: Array<{ id: string; at: number; active: boolean }> = [];
  for (const f of input.faults) for (const active of [true, false]) {
    const at = requireKnown(f.at, "us") + (active ? 0 : requireKnown(f.duration, "us"));
    kernel.schedule(at, active ? 0 : -1, identity("fault", f.id, active ? "start" : "end"), () => { stations.get(f.target)!.pause(active); faults.push({ id: f.id, at: kernel.now, active }); });
  }
  const snapshot = () => ({ at: kernel.now, counts: { ...counts, inFlight: live.size }, resources: [...stations.values()].map((s) => s.measure()) });
  const samples: ReturnType<typeof snapshot>[] = [];
  const sample = (at: number) => kernel.schedule(at, 4, identity("sample", at), () => { samples.push(snapshot()); if (at < horizon) sample(Math.min(at + step, horizon)); });
  sample(0);
  let failure: string | null = null;
  return {
    horizon,
    advanceTo(until: number) {
      if (failure) throw new Error("Failed execution cannot resume");
      if (until > horizon) throw new Error("Beyond authored horizon");
      try { kernel.advanceTo(until); } catch (e) { failure = (e as Error).message; throw e; }
    },
    evidence() {
      const state = snapshot(), terminal = counts.completed + counts.rejected + counts.deadlineExceeded + counts.abandoned;
      return copy({ modelVersion: "2", workloadVersion: input.workloadVersion, status: "internal", seed: input.seed,
        capture: { throughUs: kernel.now, reachedHorizon: kernel.now === horizon && !failure, failure },
        ...state, samples, faults, byOperation: Object.fromEntries(byOperation), sources: Object.fromEntries(sources),
        results: book.raw, resultRetention: { terminal, retained: book.raw.length, omitted: terminal - book.raw.length },
        distributions: { population: "terminal caller outcomes by operation/outcome; in-flight requests are right-censored", censored: live.size, groups: book.summary() },
        inFlight: [...live.values()].slice(0, input.limits.maxRawResults).map(({ work, receipt }) => ({ ...work, state: receipt?.state(), ageUs: kernel.now - work.offeredAt })),
        inFlightOmitted: Math.max(0, live.size - input.limits.maxRawResults),
        execution: { processed: kernel.processed, cancelled: kernel.cancelled, pending: kernel.pending, peakPending: kernel.peakPending },
        provenance: { profiles: input.profiles, ledger: input.ledger, policyLedger: WORKLOAD_POLICY_LEDGER, configuration: { resources: input.resources, operations: input.operations, limits: input.limits },
          arrivals: input.arrivals.map((a) => a.kind === "trace" ? { id: a.id, kind: a.kind, schema: a.trace.schema, durationUs: a.trace.durationUs, rows: a.trace.rows.length, provenance: a.trace.provenance } : a) },
        unmodeled: ["network transport latency", "memory", "cost", "locks", "packet loss"],
      });
    },
  };
}
